  const pageW = isFull ? slideW : landscape ? A4_H : A4_W;
  const pageH = isFull ? SLIDE_H : landscape ? A4_W : A4_H;
  const perPage = layout === "handout2" ? 2 : layout === "handout3" ? 3 : layout === "handout6" ? 6 : 1;
